{"explanation":"The graph of \(y=\tan x\) repeats every \(\pi\) and has vertical asymptotes wherever \(\cos x=0\), at \(x=\frac{\pi}{2}+k\pi\). On \([-2\pi,2\pi]\), these occur at \(-\frac{3\pi}{2},-\frac{\pi}{2},\frac{\pi}{2},\frac{3\pi}{2}\); the curve approaches but never reaches them because tangent is undefined there.","manimCode":"const ax = new Axes({
  xRange: [-2 * Math.PI, 2 * Math.PI, Math.PI / 2],
  yRange: [-4, 4, 1],
  xLength: 11,
  yLength: 5.5,
  tips: false
});
scene.add(ax, ax.getAxisLabels());

// Plot separately on intervals split by each vertical asymptote.
const eps = 0.035;
const branches = [
  [-2 * Math.PI, -3 * Math.PI / 2 - eps],
  [-3 * Math.PI / 2 + eps, -Math.PI / 2 - eps],
  [-Math.PI / 2 + eps, Math.PI / 2 - eps],
  [Math.PI / 2 + eps, 3 * Math.PI / 2 - eps],
  [3 * Math.PI / 2 + eps, 2 * Math.PI]
];
const curves = branches.map((r, i) => ax.plot(x => Math.tan(x), {
  color: [BLUE, TEAL, BLUE, TEAL, BLUE][i],
  xRange: r,
  numSamples: 240
}));
scene.add(...curves);

const asymptotes = [-3 * Math.PI / 2, -Math.PI / 2, Math.PI / 2, 3 * Math.PI / 2].map(x => {
  const line = new Line({ start: ax.c2p(x, -4), end: ax.c2p(x, 4), color: YELLOW });
  line.setOpacity(0.65);
  return line;
});
scene.add(...asymptotes);

const controls = new Controls(scene, { position: 'bottom-left', width: 230 });
controls.addButton({ label: 'Highlight asymptotes', onClick: () => {
  asymptotes.forEach(a => a.setColor(ORANGE));
}});
controls.addButton({ label: 'Reset highlight', onClick: () => {
  asymptotes.forEach(a => a.setColor(YELLOW));
}});
await scene.wait(999999);"}

